import { existsSync, writeFileSync } from 'node:fs';
import { randomBytes } from 'node:crypto';
import { join } from 'node:path';
import { hashPassword } from '../apps/api/src/lib/auth';

const file = join(import.meta.dirname, '..', '.dev.vars');
if (existsSync(file) && !process.argv.includes('--force')) {
  console.log('.dev.vars already exists (use --force to regenerate).');
} else {
  const hex = () => randomBytes(32).toString('hex');
  const password = process.env.LOCAL_ADMIN_PASSWORD ?? randomBytes(9).toString('base64url');
  const lines = [
    '# Local-only secrets generated by npm run setup:local. Never commit this file.',
    `ADMIN_PASSWORD_HASH=${await hashPassword(password)}`,
    `SESSION_SECRET=${hex()}`,
    `PHONE_HASH_SECRET=${hex()}`,
    `REPORTER_PEPPER=${hex()}`,
    `USSD_PATH_TOKEN=${hex().slice(0, 24)}`,
    'DEMO_MODE=1',
    '',
  ];
  writeFileSync(file, lines.join('\n'), { mode: 0o600 });
  console.log(`Created .dev.vars. Local admin password: ${password}`);
  console.log('(The password is only shown now; rerun with --force to make a new one.)');
}
